using Microsoft.EntityFrameworkCore;

// Cosmos DB project — EF Core 9 breaking changes applied:
// 1. Discriminator property renamed from "Discriminator" to "$type" by default.
//    Existing documents use "Discriminator", so we explicitly preserve it.
// 2. id property no longer contains the discriminator value.
//    Existing documents have "EntityType|Key" format, so we opt in to the old behavior.
// 3. Synchronous I/O (ToList, SaveChanges, etc.) now throws.
//    All queries must use async equivalents (ToListAsync, SaveChangesAsync, etc.).

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(entity =>
        {
            entity.ToContainer("Sessions");

            // Fix #1: Preserve old discriminator property name for existing documents
            entity.HasDiscriminator<string>("Discriminator");

            // Fix #2: Preserve old compound id format ("Session|<key>") for existing documents
            entity.HasRootDiscriminatorInJsonId(true);
        });
    }
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
}

// Fix #3: Synchronous Cosmos DB queries must become async.
// Example of the required change:
//
// BEFORE (throws in EF Core 9):
//   var sessions = db.Sessions.Where(s => s.Title == "test").ToList();
//   db.SaveChanges();
//
// AFTER:
//   var sessions = await db.Sessions.Where(s => s.Title == "test").ToListAsync();
//   await db.SaveChangesAsync();

